const p = $input.first().json.payload || $input.first().json;
const qa = (p.questions_and_answers || []).map(x => `${x.question}: ${x.answer}`).join('\n');
return [{ json: {
  name: p.name || `${p.first_name || ''} ${p.last_name || ''}`.trim(),
  email: p.email || '',
  meeting: p.scheduled_event?.name || 'Meeting',
  start: p.scheduled_event?.start_time || '',
  notes: qa || 'No screening answers'
} }];
